@push('scripts')<script>fetch('/enterprise/insights',{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{document.getElementById('govScore').textContent=(d.score??0)+'/100';const box=document.getElementById('insightList');box.innerHTML=(d.items||[]).map(x=>`<article class="v5-card" style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;gap:12px"><div><span class="v5-badge">${String(x.severity||'info').toUpperCase()}</span><h3 style="margin:9px 0 5px">${x.title||''}</h3><p style="margin:0;color:var(--v5-muted);font-size:11px">${x.message||''}</p></div><small style="color:var(--v5-muted)">${x.module||''}</small></div><div style="margin-top:12px;padding:10px;border-radius:10px;background:#101724;font-size:11px"><strong>Ação sugerida:</strong> ${x.action||''}</div></article>`).join('')||'<div class="v5-card">Nenhuma recomendação pendente.</div>'}).catch(()=>{document.getElementById('insightList').innerHTML='<div class="v5-alert danger">Falha ao carregar insights.</div>'});</script>@endpush
